"use strict";

const state = {
  role: "auditor",
  filter: "all",
  mode: "build",
  redactions: 0,
  generatedAt: new Date("2026-06-01T22:26:48Z").toISOString(),
};

const tasks = [
  {
    id: "S01",
    title: "Planner",
    detail: "Alcance delimitado a frontend estatico y evidencia segura.",
    status: "ready",
  },
  {
    id: "S02",
    title: "Frontend",
    detail: "Interfaz runnable con mapa visual, controles y ledger sintetico.",
    status: "ready",
  },
  {
    id: "S03",
    title: "Backend",
    detail: "Sin cambios de runtime por propiedad del control-plane.",
    status: "ready",
  },
  {
    id: "S04",
    title: "QA Browser",
    detail: "Smoke visual esperado sobre HTML, CSS y JavaScript locales.",
    status: "ready",
  },
  {
    id: "S05",
    title: "Observer",
    detail: "Findings sin hallazgos activos; integrity pendiente de retry.",
    status: "blocked",
  },
  {
    id: "S06",
    title: "LACE Docs",
    detail: "Registro acotado a la tarea y evidencia verificable.",
    status: "ready",
  },
];

const policies = [
  {
    title: "Datos sinteticos",
    detail: "La pantalla no procesa informacion sensible local ni credenciales.",
    severity: "ok",
  },
  {
    title: "Acceso por rol",
    detail: "Viewer solo consulta; Auditor y Planner pueden generar informes.",
    severity: "ok",
  },
  {
    title: "Runtime protegido",
    detail: "Los archivos internos del control-plane quedan fuera del alcance del worker.",
    severity: "warning",
  },
  {
    title: "Evidencia real",
    detail: "La validacion se basa en archivos existentes y smoke browser.",
    severity: "ok",
  },
];

const ledger = [
  {
    time: "22:26",
    actor: "S01 Planner",
    event: "Se separo la alternativa segura del prompt bloqueado.",
    evidence: "scope-redacted-001",
    status: "ready",
  },
  {
    time: "22:28",
    actor: "S02 Frontend",
    event: "Se preparo UI estatica con datos sinteticos.",
    evidence: "frontend-build-002",
    status: "ready",
  },
  {
    time: "22:29",
    actor: "S05 Observer",
    event: "Findings activos en cero; integrity requiere retry.",
    evidence: "observer-compact-003",
    status: "blocked",
  },
  {
    time: "22:31",
    actor: "S06 LACE Docs",
    event: "Se registro ciclo acotado para la tarea actual.",
    evidence: "lace-log-004",
    status: "ready",
  },
];

const nodes = [
  { id: "index", label: "index.html", x: 0.17, y: 0.24, status: "ready" },
  { id: "styles", label: "styles.css", x: 0.48, y: 0.18, status: "ready" },
  { id: "app", label: "app.js", x: 0.76, y: 0.27, status: "ready" },
  { id: "findings", label: "findings", x: 0.28, y: 0.69, status: "ready" },
  { id: "integrity", label: "integrity", x: 0.64, y: 0.72, status: "blocked" },
];

const links = [
  ["index", "styles"],
  ["index", "app"],
  ["app", "findings"],
  ["app", "integrity"],
];

const permissions = {
  auditor: { label: "Auditor", canExport: true, canRedact: true },
  planner: { label: "Planner", canExport: true, canRedact: true },
  viewer: { label: "Viewer", canExport: false, canRedact: false },
};

const dom = {
  roleSelect: document.getElementById("roleSelect"),
  modePill: document.getElementById("modePill"),
  filesMetric: document.getElementById("filesMetric"),
  riskMetric: document.getElementById("riskMetric"),
  redactionMetric: document.getElementById("redactionMetric"),
  accessMetric: document.getElementById("accessMetric"),
  queueCount: document.getElementById("queueCount"),
  taskList: document.getElementById("taskList"),
  mapSummary: document.getElementById("mapSummary"),
  canvas: document.getElementById("world"),
  policySummary: document.getElementById("policySummary"),
  policyList: document.getElementById("policyList"),
  ledgerSummary: document.getElementById("ledgerSummary"),
  ledgerBody: document.getElementById("ledgerBody"),
  speedValue: document.getElementById("speed-value"),
  distanceValue: document.getElementById("distance-value"),
  eventValue: document.getElementById("event-value"),
  redactButton: document.getElementById("redactButton"),
  exportButton: document.getElementById("exportButton"),
  reportModal: document.getElementById("reportModal"),
  reportOutput: document.getElementById("reportOutput"),
  closeReport: document.getElementById("closeReport"),
};

function createEl(tag, className, text) {
  const element = document.createElement(tag);
  if (className) {
    element.className = className;
  }
  if (text !== undefined) {
    element.textContent = text;
  }
  return element;
}

function getFilteredItems(items) {
  if (state.filter === "all") {
    return items;
  }
  return items.filter((item) => item.status === state.filter);
}

function renderMetrics() {
  const blockedCount = tasks.filter((task) => task.status === "blocked").length;
  const readyFiles = ["frontend/index.html", "frontend/styles.css", "frontend/app.js"];
  dom.filesMetric.textContent = `${readyFiles.length}/3`;
  dom.riskMetric.textContent = blockedCount > 0 ? "Medio" : "Bajo";
  dom.redactionMetric.textContent = String(state.redactions);
  dom.accessMetric.textContent = permissions[state.role].label;
  dom.modePill.textContent = `Mode: ${state.mode}`;
}

function renderTasks() {
  const filteredTasks = getFilteredItems(tasks);
  dom.queueCount.textContent = `${filteredTasks.length} tareas`;
  dom.taskList.replaceChildren();

  filteredTasks.forEach((task) => {
    const item = createEl("article", "task-item");
    const topline = createEl("div", "task-topline");
    topline.append(
      createEl("span", "task-title", `${task.id} ${task.title}`),
      createEl("span", `task-status ${task.status}`, task.status),
    );
    item.append(topline, createEl("p", "", task.detail));
    dom.taskList.append(item);
  });
}

function renderPolicies() {
  dom.policyList.replaceChildren();
  policies.forEach((policy) => {
    const item = createEl("li", policy.severity === "warning" ? "policy-item warning" : "policy-item");
    item.append(createEl("strong", "", policy.title), createEl("span", "", policy.detail));
    dom.policyList.append(item);
  });
  dom.policySummary.textContent = permissions[state.role].canExport ? "Exportable" : "Lectura";
}

function renderLedger() {
  const filteredLedger = getFilteredItems(ledger);
  dom.ledgerBody.replaceChildren();
  filteredLedger.forEach((entry) => {
    const row = document.createElement("tr");
    [entry.time, entry.actor, entry.event, entry.evidence].forEach((value) => {
      row.append(createEl("td", "", value));
    });
    const statusCell = createEl("td");
    statusCell.append(createEl("span", `state-dot ${entry.status}`, entry.status));
    row.append(statusCell);
    dom.ledgerBody.append(row);
  });
  dom.ledgerSummary.textContent = `${filteredLedger.length} eventos visibles para ${permissions[state.role].label}.`;
}

function renderControls() {
  const permission = permissions[state.role];
  dom.redactButton.disabled = !permission.canRedact;
  dom.exportButton.disabled = !permission.canExport;
  dom.redactButton.title = permission.canRedact ? "" : "Rol sin permiso de redaccion";
  dom.exportButton.title = permission.canExport ? "" : "Rol sin permiso de informe";
}

function renderHud() {
  const visibleNodes = getFilteredItems(nodes).length;
  const visibleLedger = getFilteredItems(ledger).length;
  const speed = Math.max(12, visibleLedger * 6);
  dom.speedValue.textContent = `${speed} m/s`;
  dom.distanceValue.textContent = `${visibleNodes} nodos / 3 archivos`;
  dom.eventValue.textContent = state.filter === "blocked" ? "fallback-2d blocked view" : "fallback-2d ready";
}

function drawCanvas() {
  const canvas = dom.canvas;
  const rect = canvas.getBoundingClientRect();
  const width = Math.max(320, Math.floor(rect.width));
  const height = Math.max(300, Math.floor(rect.height));
  const ratio = window.devicePixelRatio || 1;
  canvas.width = Math.floor(width * ratio);
  canvas.height = Math.floor(height * ratio);
  const ctx = canvas.getContext("2d");
  ctx.setTransform(ratio, 0, 0, ratio, 0, 0);
  ctx.clearRect(0, 0, width, height);

  const activeNodes = getFilteredItems(nodes);
  const byId = new Map(activeNodes.map((node) => [node.id, node]));

  ctx.fillStyle = "#f8fbfa";
  ctx.fillRect(0, 0, width, height);

  ctx.strokeStyle = "#d9e2dd";
  ctx.lineWidth = 1;
  for (let i = 0; i < width; i += 38) {
    ctx.beginPath();
    ctx.moveTo(i, 0);
    ctx.lineTo(i, height);
    ctx.stroke();
  }
  for (let i = 0; i < height; i += 38) {
    ctx.beginPath();
    ctx.moveTo(0, i);
    ctx.lineTo(width, i);
    ctx.stroke();
  }

  links.forEach(([fromId, toId]) => {
    const from = byId.get(fromId);
    const to = byId.get(toId);
    if (!from || !to) {
      return;
    }
    ctx.beginPath();
    ctx.moveTo(from.x * width, from.y * height);
    ctx.lineTo(to.x * width, to.y * height);
    ctx.strokeStyle = "#8ea19a";
    ctx.lineWidth = 2;
    ctx.stroke();
  });

  activeNodes.forEach((node) => {
    const x = node.x * width;
    const y = node.y * height;
    const radius = 30;
    const fill = node.status === "blocked" ? "#f8dedd" : "#dff5ec";
    const stroke = node.status === "blocked" ? "#ad3535" : "#176f53";

    ctx.beginPath();
    ctx.arc(x, y, radius, 0, Math.PI * 2);
    ctx.fillStyle = fill;
    ctx.fill();
    ctx.strokeStyle = stroke;
    ctx.lineWidth = 3;
    ctx.stroke();

    ctx.fillStyle = "#17201d";
    ctx.font = "700 13px system-ui, sans-serif";
    ctx.textAlign = "center";
    ctx.fillText(node.label, x, y + radius + 22);
  });

  dom.mapSummary.textContent = `${activeNodes.length} nodos`;
}

function buildReport() {
  return {
    projectSlug: "sesion-20260601004224-alternativa-segura-2",
    generatedAt: new Date().toISOString(),
    mode: state.mode,
    role: state.role,
    dataSource: "synthetic",
    sensitiveLocalProcessing: false,
    expectedFiles: ["frontend/index.html", "frontend/styles.css", "frontend/app.js"],
    visibleTasks: getFilteredItems(tasks).map((task) => ({
      id: task.id,
      title: task.title,
      status: task.status,
    })),
    visibleLedger: getFilteredItems(ledger).map((entry) => ({
      time: entry.time,
      actor: entry.actor,
      event: entry.event,
      evidence: `[redacted:${entry.evidence.slice(-3)}]`,
      status: entry.status,
    })),
  };
}

function openReport() {
  if (!permissions[state.role].canExport) {
    return;
  }
  dom.reportOutput.textContent = JSON.stringify(buildReport(), null, 2);
  if (typeof dom.reportModal.showModal === "function") {
    dom.reportModal.showModal();
  } else {
    dom.reportModal.setAttribute("open", "open");
  }
}

function closeReport() {
  if (typeof dom.reportModal.close === "function") {
    dom.reportModal.close();
  } else {
    dom.reportModal.removeAttribute("open");
  }
}

function redactVisibleEvidence() {
  if (!permissions[state.role].canRedact) {
    return;
  }
  state.redactions += getFilteredItems(ledger).length;
  render();
}

function render() {
  renderMetrics();
  renderTasks();
  renderPolicies();
  renderLedger();
  renderControls();
  renderHud();
  drawCanvas();
}

function bindEvents() {
  dom.roleSelect.addEventListener("change", (event) => {
    state.role = event.target.value;
    render();
  });

  document.querySelectorAll("[data-filter]").forEach((button) => {
    button.addEventListener("click", () => {
      state.filter = button.dataset.filter;
      document.querySelectorAll("[data-filter]").forEach((item) => {
        item.classList.toggle("active", item === button);
      });
      render();
    });
  });

  dom.redactButton.addEventListener("click", redactVisibleEvidence);
  dom.exportButton.addEventListener("click", openReport);
  dom.closeReport.addEventListener("click", closeReport);
  window.addEventListener("resize", drawCanvas);
}

bindEvents();
render();

:root {
  color-scheme: light;
  --bg: #f5f7f8;
  --ink: #17201d;
  --muted: #66746d;
  --surface: #ffffff;
  --surface-soft: #edf3f0;
  --line: #d9e2dd;
  --green: #176f53;
  --green-strong: #0f5e45;
  --blue: #315f9f;
  --amber: #a65f00;
  --red: #ad3535;
  --shadow: 0 18px 45px rgba(28, 38, 34, 0.12);
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-width: 320px;
  background: var(--bg);
  color: var(--ink);
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  letter-spacing: 0;
}

button,
select {
  font: inherit;
}

button {
  cursor: pointer;
}

.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  padding: 20px clamp(18px, 4vw, 48px);
  background: #0f211c;
  color: #f8fbfa;
  border-bottom: 1px solid rgba(255, 255, 255, 0.12);
}

.brand-block,
.status-rail,
.control-band,
.control-group,
.control-actions,
.panel-heading,
.section-heading,
.modal-header {
  display: flex;
  align-items: center;
}

.brand-block {
  gap: 14px;
  min-width: 0;
}

.brand-mark {
  display: grid;
  flex: 0 0 auto;
  width: 46px;
  height: 46px;
  place-items: center;
  border-radius: 8px;
  background: #dff5ec;
  color: #113328;
  font-weight: 800;
}

h1,
h2,
p {
  margin: 0;
}

h1 {
  font-size: clamp(1.35rem, 2.4vw, 2rem);
  line-height: 1.05;
}

.brand-block p {
  margin-top: 5px;
  color: #b8c9c2;
  font-size: 0.95rem;
}

.status-rail {
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 8px;
}

.status-pill {
  display: inline-flex;
  min-height: 32px;
  align-items: center;
  border-radius: 999px;
  padding: 6px 12px;
  background: rgba(255, 255, 255, 0.12);
  color: #f8fbfa;
  font-size: 0.83rem;
  font-weight: 700;
  white-space: nowrap;
}

.status-pill.ok {
  background: #dff5ec;
  color: #0f5e45;
}

.status-pill.guard {
  background: #e6eefb;
  color: #2c568f;
}

.status-pill.neutral {
  background: #f5ead8;
  color: #784600;
}

.app-shell {
  width: min(1480px, 100%);
  margin: 0 auto;
  padding: 22px clamp(14px, 3vw, 42px) 44px;
}

.control-band {
  justify-content: space-between;
  gap: 16px;
  padding: 14px;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 8px;
  box-shadow: var(--shadow);
}

.control-group {
  gap: 10px;
}

.control-group label {
  color: var(--muted);
  font-size: 0.9rem;
  font-weight: 700;
}

select {
  min-height: 40px;
  max-width: 180px;
  border: 1px solid var(--line);
  border-radius: 6px;
  padding: 0 34px 0 12px;
  background: var(--surface);
  color: var(--ink);
}

.segmented {
  display: grid;
  grid-template-columns: repeat(3, minmax(74px, 1fr));
  min-height: 40px;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--surface-soft);
}

.segment {
  border: 0;
  border-right: 1px solid var(--line);
  background: transparent;
  color: var(--muted);
  font-weight: 800;
}

.segment:last-child {
  border-right: 0;
}

.segment.active {
  background: var(--green);
  color: white;
}

.control-actions {
  gap: 10px;
}

.primary-action,
.secondary-action,
.icon-button {
  min-height: 40px;
  border-radius: 7px;
  border: 1px solid transparent;
  font-weight: 800;
}

.primary-action,
.secondary-action {
  min-width: 108px;
  padding: 0 14px;
}

.primary-action {
  background: var(--green);
  color: white;
}

.primary-action:hover,
.primary-action:focus-visible {
  background: var(--green-strong);
}

.secondary-action {
  background: #e6eefb;
  color: var(--blue);
  border-color: #c6d6ee;
}

.metric-strip {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 14px;
  margin-top: 16px;
}

.metric,
.panel,
.ledger-section {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 8px;
  box-shadow: 0 12px 30px rgba(28, 38, 34, 0.08);
}

.metric {
  min-height: 96px;
  padding: 16px;
}

.metric-label {
  display: block;
  min-height: 20px;
  color: var(--muted);
  font-size: 0.84rem;
  font-weight: 800;
  text-transform: uppercase;
}

.metric strong {
  display: block;
  margin-top: 12px;
  font-size: clamp(1.4rem, 3vw, 2.2rem);
  line-height: 1;
}

.workspace-grid {
  display: grid;
  grid-template-columns: minmax(240px, 0.9fr) minmax(360px, 1.55fr) minmax(240px, 0.8fr);
  gap: 16px;
  margin-top: 16px;
  align-items: stretch;
}

.panel {
  min-height: 426px;
  padding: 16px;
}

.panel-heading,
.section-heading,
.modal-header {
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 14px;
}

.panel-heading h2,
.section-heading h2,
.modal-header h2 {
  font-size: 1.05rem;
  line-height: 1.2;
}

.panel-heading span,
.section-heading p {
  color: var(--muted);
  font-size: 0.88rem;
  font-weight: 700;
}

.task-list {
  display: grid;
  gap: 10px;
}

.task-item {
  display: grid;
  gap: 8px;
  min-height: 92px;
  padding: 12px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: #fbfcfc;
}

.task-topline {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.task-title {
  font-weight: 850;
  overflow-wrap: anywhere;
}

.task-status {
  flex: 0 0 auto;
  border-radius: 999px;
  padding: 4px 8px;
  font-size: 0.73rem;
  font-weight: 900;
}

.task-status.ready {
  background: #dff5ec;
  color: var(--green-strong);
}

.task-status.blocked {
  background: #f8dedd;
  color: var(--red);
}

.task-item p {
  color: var(--muted);
  font-size: 0.9rem;
  line-height: 1.45;
}

.map-panel {
  display: flex;
  flex-direction: column;
}

#world {
  display: block;
  width: 100%;
  min-height: 338px;
  flex: 1;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: #f8fbfa;
}

.live-hud {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
  margin-top: 10px;
}

.live-hud span {
  display: grid;
  gap: 4px;
  min-height: 58px;
  align-content: center;
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 9px 10px;
  background: #fbfcfc;
  color: var(--muted);
  font-size: 0.78rem;
  font-weight: 800;
  text-transform: uppercase;
}

.live-hud strong {
  color: var(--ink);
  font-size: 0.98rem;
  line-height: 1.15;
  text-transform: none;
  overflow-wrap: anywhere;
}

.policy-list {
  display: grid;
  gap: 10px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.policy-item {
  padding: 12px;
  border-left: 4px solid var(--green);
  border-radius: 7px;
  background: #f8fbfa;
}

.policy-item.warning {
  border-left-color: var(--amber);
}

.policy-item strong {
  display: block;
  margin-bottom: 5px;
}

.policy-item span {
  color: var(--muted);
  font-size: 0.9rem;
  line-height: 1.45;
}

.ledger-section {
  margin-top: 16px;
  padding: 16px;
}

.table-wrap {
  overflow-x: auto;
}

table {
  width: 100%;
  min-width: 760px;
  border-collapse: collapse;
}

th,
td {
  border-bottom: 1px solid var(--line);
  padding: 13px 10px;
  text-align: left;
  vertical-align: top;
}

th {
  color: var(--muted);
  font-size: 0.78rem;
  text-transform: uppercase;
}

td {
  font-size: 0.93rem;
}

.state-dot {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-weight: 800;
}

.state-dot::before {
  content: "";
  width: 9px;
  height: 9px;
  border-radius: 999px;
  background: var(--green);
}

.state-dot.blocked::before {
  background: var(--red);
}

.report-modal {
  width: min(760px, calc(100% - 28px));
  max-height: min(720px, calc(100% - 28px));
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 18px;
  box-shadow: var(--shadow);
}

.report-modal::backdrop {
  background: rgba(15, 33, 28, 0.5);
}

.icon-button {
  width: 40px;
  background: #f0f3f2;
  color: var(--ink);
}

pre {
  max-height: 540px;
  overflow: auto;
  margin: 0;
  padding: 14px;
  border-radius: 8px;
  background: #101b18;
  color: #e5f7ef;
  font-size: 0.88rem;
  line-height: 1.5;
  white-space: pre-wrap;
}

button:focus-visible,
select:focus-visible {
  outline: 3px solid rgba(49, 95, 159, 0.35);
  outline-offset: 2px;
}

@media (max-width: 1080px) {
  .workspace-grid {
    grid-template-columns: 1fr 1fr;
  }

  .policy-panel {
    grid-column: 1 / -1;
    min-height: auto;
  }
}

@media (max-width: 820px) {
  .topbar,
  .control-band {
    align-items: stretch;
    flex-direction: column;
  }

  .status-rail {
    justify-content: flex-start;
  }

  .control-actions {
    display: grid;
    grid-template-columns: 1fr 1fr;
  }

  .primary-action,
  .secondary-action {
    width: 100%;
    min-width: 0;
  }

  .metric-strip,
  .workspace-grid {
    grid-template-columns: 1fr;
  }

  .panel {
    min-height: auto;
  }

  #world {
    min-height: 300px;
  }
}

@media (max-width: 520px) {
  .brand-block {
    align-items: flex-start;
  }

  .brand-mark {
    width: 40px;
    height: 40px;
  }

  .segmented {
    grid-template-columns: 1fr;
  }

  .live-hud {
    grid-template-columns: 1fr;
  }

  .segment {
    min-height: 38px;
    border-right: 0;
    border-bottom: 1px solid var(--line);
  }

  .segment:last-child {
    border-bottom: 0;
  }
}
